【LetMeFly】592.分数加减运算：手把手分步のC++讲解力扣题目链接：https://leetcode.cn/problems/fraction-addition-and-subtraction/
给定一个表示分数加减运算的字符串&nbsp;expression&nbsp;，你需要返回一个字符串形式的计算结果。&nbsp;

这个结果应该是不可约分的分数，即最简分数。&nbsp;如果最终结果是一个整数，例如&nbsp;2，你需要将它转换成分数形式，其分母为&nbsp;1。所以在上述例子中, 2&nbsp;应该被转换为&nbsp;2/1。

&nbsp;

示例&nbsp;1:


输入:&nbsp;expression&nbsp;= "-1/2+1/2"
输出: "0/1"


&nbsp;示例 2:


输入:&nbsp;expression&nbsp;= "-1/2+1/2+1/3"
输出: "1/3"


示例 3:


输入:&nbsp;expression&nbsp;= "1/3-1/2"
输出: "-1/6"


&nbsp;

提示:


	输入和输出字符串只包含&nbsp;'0' 到&nbsp;'9'&nbsp;的数字，以及&nbsp;'/', '+' 和&nbsp;'-'。&nbsp;
	输入和输出分数格式均为&nbsp;±分子/分母。如果输入的第一个分数或者输出的分数是正数，则&nbsp;'+'&nbsp;会被省略掉。
	输入只包含合法的最简分数，每个分数的分子与分母的范围是&nbsp;&nbsp;[1,10]。&nbsp;如果分母是1，意味着这个分数实际上是一个整数。
	输入的分数个数范围是 [1,10]。
	最终结果的分子与分母保证是 32 位整数范围内的有效整数。




方法一：C++模拟用pair&lt;int, int&gt;表示分数，然后不断模拟即可。
主要需要实现三个功能：

字符串转分数 字符串转分数稍微复杂一些。 首先根据字符串的首个字符判断分数的正负，然后计算分子和分母分别对应字符串中的哪几个字符，最后再把字符串转为int即可。    pii string2fraction(string s) &#123;	pii ans;	// 判断分数的正负	if (s[0] == &#x27;-&#x27;) &#123;		ans.first = -1;	&#125;	else &#123;		ans.first = 1;	&#125;	// 计算分子开始位置的下标	int l = 0;	if (s[0] == &#x27;-&#x27; || s[0] == &#x27;+&#x27;) &#123;		l++;	&#125;	// 计算分子结束位置的下标	int r = l;	while (s[r] != &#x27;/&#x27;)		r++;	// 计算分子分母	ans.first *= atoi(s.substr(l, r - l).c_str());	ans.second = atoi(s.substr(r + 1, s.size() - r -1).c_str());	return ans;&#125;
两个分数相加 分数相加首先要通分。 令新的分母为原本两个分数的最小公倍数，然后将两个分数的分子分别化为通分后的值并累加，最后进行约分即可。 注意分子分母约分的时候，__gcd()函数调用时记得传入分子分母的绝对值，否则求得的最小公倍数可能会为负数。 pii add(pii p1, pii p2) &#123;    pii ans;    ans.second = p1.second * p2.second / __gcd(p1.second, p2.second);    ans.first = p1.first * (ans.second / p1.second) + p2.first * (ans.second / p2.second);    int gcd = __gcd(abs(ans.first), ans.second);    ans.first /= gcd, ans.second /= gcd;    return ans;&#125;
将分数转为字符串 这个功能实现起来相对容易，只需要将分子分母分别转为字符串，并在中间加上/即可。 string fraction2string(pii f) &#123;    return to_string(f.first) + &quot;/&quot; + to_string(f.second);&#125;

实现了上述三个功能，只需要在主函数中对原始字符串按加减号进行分割，并把每个分割出来的分数的值累加即可。
string fractionAddition(string expression) &#123;	pii ans = &#123;0, 1&#125;;	int last = 0;  // 上一个处理到的字符的位置	for (int i = 1; i &lt; expression.size(); i++) &#123;		if (expression[i] == &#x27;+&#x27; || expression[i] == &#x27;-&#x27;) &#123;  // 遇到加减号就开始分割			ans = add(ans, string2fraction(expression.substr(last, i - last)));			last = i;		&#125;	&#125;	ans = add(ans, string2fraction(expression.substr(last, expression.size() - last)));  // 注意字符串末尾没有加减号，不要把最后一个分数遗漏了。	return fraction2string(ans);&#125;

拓展：
如果想要debug分数长啥样，可以直接重载运算符&lt;&lt;
ostream &amp;operator &lt;&lt; (ostream&amp; out, pii&amp; p) &#123;    out &lt;&lt; p.first &lt;&lt; &quot;/&quot; &lt;&lt; p.second;    return out;&#125;

这样，当想要debug时，就可以直接
pair&lt;int, int&gt; fraction = &#123;1, 2&#125;;cout &lt;&lt; fraction &lt;&lt; endl;

了。

时间复杂度$O(n)$，其中$n$是字符串长度
空间复杂度$O(m)$，其中$m$是一个分数的字符串的平均长度

AC代码C++typedef pair&lt;int, int&gt; pii;ostream &amp;operator &lt;&lt; (ostream&amp; out, pii&amp; p) &#123;    out &lt;&lt; p.first &lt;&lt; &quot;/&quot; &lt;&lt; p.second;    return out;&#125;class Solution &#123;private:    pii string2fraction(string s) &#123;        pii ans;        if (s[0] == &#x27;-&#x27;) &#123;            ans.first = -1;        &#125;        else &#123;            ans.first = 1;        &#125;        int l = 0;        if (s[0] == &#x27;-&#x27; || s[0] == &#x27;+&#x27;) &#123;            l++;        &#125;        int r = l;        while (s[r] != &#x27;/&#x27;)            r++;        ans.first *= atoi(s.substr(l, r - l).c_str());        ans.second = atoi(s.substr(r + 1, s.size() - r - 1).c_str());        // cout &lt;&lt; s &lt;&lt; &quot; -&gt; &quot; &lt;&lt; ans &lt;&lt; endl;        return ans;    &#125;    pii add(pii p1, pii p2) &#123;        pii ans;        ans.second = p1.second * p2.second / __gcd(p1.second, p2.second);        ans.first = p1.first * (ans.second / p1.second) + p2.first * (ans.second / p2.second);        int gcd = __gcd(abs(ans.first), ans.second);        ans.first /= gcd, ans.second /= gcd;        return ans;    &#125;    string fraction2string(pii f) &#123;        return to_string(f.first) + &quot;/&quot; + to_string(f.second);    &#125;public:    string fractionAddition(string expression) &#123;        pii ans = &#123;0, 1&#125;;        int last = 0;        for (int i = 1; i &lt; expression.size(); i++) &#123;            if (expression[i] == &#x27;+&#x27; || expression[i] == &#x27;-&#x27;) &#123;                ans = add(ans, string2fraction(expression.substr(last, i - last)));                last = i;            &#125;        &#125;        ans = add(ans, string2fraction(expression.substr(last, expression.size() - last)));        return fraction2string(ans);    &#125;&#125;;


