【LetMeFly】3531.统计被覆盖的建筑：最大最小值力扣题目链接：https://leetcode.cn/problems/count-covered-buildings/
给你一个正整数 n，表示一个 n x n 的城市，同时给定一个二维数组 buildings，其中 buildings[i] = [x, y] 表示位于坐标 [x, y] 的一个&nbsp;唯一&nbsp;建筑。

如果一个建筑在四个方向（左、右、上、下）中每个方向上都至少存在一个建筑，则称该建筑&nbsp;被覆盖&nbsp;。

返回&nbsp;被覆盖&nbsp;的建筑数量。

&nbsp;

示例 1：




输入: n = 3, buildings = [[1,2],[2,2],[3,2],[2,1],[2,3]]

输出: 1

解释:


	只有建筑 [2,2] 被覆盖，因为它在每个方向上都至少存在一个建筑：

&lt;ul&gt;
	&lt;li&gt;上方 (&lt;code&gt;[1,2]&lt;/code&gt;)&lt;/li&gt;
	&lt;li&gt;下方 (&lt;code&gt;[3,2]&lt;/code&gt;)&lt;/li&gt;
	&lt;li&gt;左方 (&lt;code&gt;[2,1]&lt;/code&gt;)&lt;/li&gt;
	&lt;li&gt;右方 (&lt;code&gt;[2,3]&lt;/code&gt;)&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;因此，被覆盖的建筑数量是 1。&lt;/li&gt;




示例 2：




输入: n = 3, buildings = [[1,1],[1,2],[2,1],[2,2]]

输出: 0

解释:


	没有任何一个建筑在每个方向上都有至少一个建筑。



示例 3：




输入: n = 5, buildings = [[1,3],[3,2],[3,3],[3,5],[5,3]]

输出: 1

解释:


	只有建筑 [3,3] 被覆盖，因为它在每个方向上至少存在一个建筑：

&lt;ul&gt;
	&lt;li&gt;上方 (&lt;code&gt;[1,3]&lt;/code&gt;)&lt;/li&gt;
	&lt;li&gt;下方 (&lt;code&gt;[5,3]&lt;/code&gt;)&lt;/li&gt;
	&lt;li&gt;左方 (&lt;code&gt;[3,2]&lt;/code&gt;)&lt;/li&gt;
	&lt;li&gt;右方 (&lt;code&gt;[3,5]&lt;/code&gt;)&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;因此，被覆盖的建筑数量是 1。&lt;/li&gt;




&nbsp;

提示：


	2 &lt;= n &lt;= 105
	1 &lt;= buildings.length &lt;= 105
	buildings[i] = [x, y]
	1 &lt;= x, y &lt;= n
	buildings 中所有坐标均&nbsp;唯一&nbsp;。




解题方法：最大最小值遍历一遍所有点可以得到如下信息：

使用两个数组xm和xM，分别记录所有横坐标为x的点中纵坐标的最小值和最大值；
使用两个数组ym和yM，分别记录所有纵坐标为y的点中横坐标的最小值和最大值。

接着遍历一遍所有点（假设横纵坐标分别是x和y）：

如果$ym[y]\lt x\lt yM[y]$并且$xm[x]\lt y\lt xM[x]$则说明这个点上下左右都有点，答案加一。


时间复杂度$O(n+len(buildings))$
空间复杂度$O(n)$

AC代码C++/* * @LastEditTime: 2025-12-11 13:23:40 */class Solution &#123;public:    int countCoveredBuildings(int n, vector&lt;vector&lt;int&gt;&gt;&amp; buildings) &#123;        n++;        vector&lt;int&gt; xm(n, n), xM(n), ym(n, n), yM(n);        for (vector&lt;int&gt;&amp; building : buildings) &#123;            int x = building[0], y = building[1];            xm[x] = min(xm[x], y);            xM[x] = max(xM[x], y);            ym[y] = min(ym[y], x);            yM[y] = max(yM[y], x);        &#125;        int ans = 0;        for (vector&lt;int&gt;&amp; building : buildings) &#123;            int x = building[0], y = building[1];            ans += xm[x] &lt; y &amp;&amp; y &lt; xM[x] &amp;&amp; ym[y] &lt; x &amp;&amp; x &lt; yM[y];        &#125;        return ans;    &#125;&#125;;

Python&#x27;&#x27;&#x27;LastEditTime: 2025-12-11 13:27:34&#x27;&#x27;&#x27;from typing import Listclass Solution:    def countCoveredBuildings(self, n: int, buildings: List[List[int]]) -&gt; int:        n += 1        xm = [n] * n        xM = [0] * n        ym = [n] * n        yM = [0] * n        for x, y in buildings:            xm[x] = min(xm[x], y)            xM[x] = max(xM[x], y)            ym[y] = min(ym[y], x)            yM[y] = max(yM[y], x)        ans = 0        for x, y in buildings:            ans += xm[x] &lt; y &lt; xM[x] and ym[y] &lt; x &lt; yM[y]        return ans

Java/* * @LastEditTime: 2025-12-11 13:40:24 */import java.util.Arrays;class Solution &#123;    public int countCoveredBuildings(int n, int[][] buildings) &#123;        n++;        int[] xm = new int[n];        int[] xM = new int[n];        int[] ym = new int[n];        int[] yM = new int[n];        Arrays.fill(xm, n);        Arrays.fill(ym, n);        for (int[] building : buildings) &#123;            int x = building[0], y = building[1];            xm[x] = Math.min(xm[x], y);            xM[x] = Math.max(xM[x], y);            ym[y] = Math.min(ym[y], x);            yM[y] = Math.max(yM[y], x);        &#125;        int ans = 0;        for (int[] building : buildings) &#123;            int x = building[0], y = building[1];            if (xm[x] &lt; y &amp;&amp; y &lt; xM[x] &amp;&amp; ym[y] &lt; x &amp;&amp; x &lt; yM[y]) &#123;                ans++;            &#125;        &#125;        return ans;    &#125;&#125;

Go/* * @LastEditTime: 2025-12-11 13:35:38 */package mainfunc countCoveredBuildings(n int, buildings [][]int) (ans int) &#123;    n++    xm := make([]int, n)    xM := make([]int, n)    ym := make([]int, n)    yM := make([]int, n)    for i := range xm &#123;        xm[i] = n        ym[i] = n    &#125;    for _, building := range buildings &#123;        x, y := building[0], building[1]        xm[x] = min(xm[x], y)        xM[x] = max(xM[x], y)        ym[y] = min(ym[y], x)        yM[y] = max(yM[y], x)    &#125;    for _, building := range buildings &#123;        x, y := building[0], building[1]        if xm[x] &lt; y &amp;&amp; y &lt; xM[x] &amp;&amp; ym[y] &lt; x &amp;&amp; x &lt; yM[y] &#123;            ans++        &#125;    &#125;    return&#125;

Rust/* * @LastEditTime: 2025-12-11 13:48:09 */impl Solution &#123;    pub fn count_covered_buildings(mut n: i32, buildings: Vec&lt;Vec&lt;i32&gt;&gt;) -&gt; i32 &#123;        n += 1;        let mut xm: Vec&lt;i32&gt; = vec![n; n as usize];        let mut xM: Vec&lt;i32&gt; = vec![0; n as usize];        let mut ym: Vec&lt;i32&gt; = vec![n; n as usize];        let mut yM: Vec&lt;i32&gt; = vec![0; n as usize];        for building in buildings.iter() &#123;            let x: i32 = building[0];            let y: i32 = building[1];            xm[x as usize] = xm[x as usize].min(y);            xM[x as usize] = xM[x as usize].max(y);            ym[y as usize] = ym[y as usize].min(x);            yM[y as usize] = yM[y as usize].max(x);        &#125;        let mut ans: i32 = 0;        for building in buildings.iter() &#123;            let x: i32 = building[0];            let y: i32 = building[1];            if xm[x as usize] &lt; y &amp;&amp; y &lt; xM[x as usize] &amp;&amp; ym[y as usize] &lt; x &amp;&amp; x &lt; yM[y as usize] &#123;                ans += 1;            &#125;        &#125;        ans    &#125;&#125;


