循环队列的纯C语言实现其中SIZE为5，实则只能存放最多4个元素（否则需要专门记录元素个数是0还是5）
本来想用结构体实现的，但纯C的结构体没有private或者成员函数，因此就开全局变量了。
#include &lt;stdio.h&gt;#include &lt;string.h&gt;#define SIZE 5int a[SIZE];int head = 0, tail = 0;int next(int now) &#123;    return (now + 1) % SIZE;&#125;void push(int n) &#123;    a[tail] = n;    tail = next(tail);&#125;int pop() &#123;    int val = a[head];    head = next(head);    return val;&#125;int size() &#123;    return (tail - head + SIZE) % SIZE;&#125;int main() &#123;    while (1) &#123;        char op[10];        puts(&quot;push or pop or size or exit? &quot;);        scanf(&quot;%s&quot;, op);        if (!strcmp(op, &quot;push&quot;)) &#123;            if (size() == SIZE) &#123;                puts(&quot;Error! no more space&quot;);            &#125;            else &#123;                int t;                puts(&quot;push what? &quot;);                scanf(&quot;%d&quot;, &amp;t);                push(t);            &#125;        &#125;        else if (!strcmp(op, &quot;pop&quot;)) &#123;            if (!size()) &#123;                puts(&quot;Error! The queue is empty!&quot;);            &#125;            else &#123;                printf(&quot;%d\n&quot;, pop());            &#125;        &#125;        else if (!strcmp(op, &quot;size&quot;)) &#123;            int nowSize = size();            printf(&quot;The size of the queue is %d\n&quot;, nowSize);        &#125;        else if (!strcmp(op, &quot;exit&quot;)) &#123;            puts(&quot;Bye~&quot;);            break;        &#125;        else &#123;            puts(&quot;Error option!&quot;);        &#125;    &#125;    return 0;&#125;

