#include &lt;iostream&gt;using namespace std;#define ERROR 0#define OK 1#define OVERFLOW 2 // --------------------------------------#define MAXQSIZE 100typedef int QElemType;typedef int Status;//队列的顺序存储结构typedef struct &#123;	QElemType *base; //存储空间的基地址	int front;		 //头指针	int rear;		 //尾指针&#125; SqQueue;Status InitQueue(SqQueue &amp;);			//初始化队列Status EnQueue(SqQueue &amp;, QElemType);	//入队Status DeQueue(SqQueue &amp;, QElemType &amp;); //出队Status QueueLength(SqQueue);			//队列长度Status QueueTraverse(SqQueue);			//输出队列int main() &#123;	SqQueue S;	int e, a;	if (InitQueue(S))		cout &lt;&lt; &quot;循环队列初始化成功！&quot; &lt;&lt; endl;	else		cout &lt;&lt; &quot;循环队列初始化失败！&quot; &lt;&lt; endl;	while (1) &#123;		cout &lt;&lt; &quot;\n【1】入队  【2】出队  【3】输出队列  【4】求队列长度  【0】退出&quot; &lt;&lt; endl;		cout &lt;&lt; &quot;请选择要进行的操作：&quot;;		cin &gt;&gt; a;		switch (a) &#123;		case 1:			int x, n;			cout &lt;&lt; &quot;请输入要插入的元素个数：&quot;;			cin &gt;&gt; n;			for (int i = 0; i &lt; n; i++) &#123;				cout &lt;&lt; &quot;请输入第&quot; &lt;&lt; i + 1 &lt;&lt; &quot;元素值：&quot;;				cin &gt;&gt; x;				EnQueue(S, x);			&#125;			cout &lt;&lt; &quot;入队完成！&quot; &lt;&lt; endl;			break;  // ---------------------------------------------- 这里忘了break		case 2:			cout &lt;&lt; &quot;请输入要删除的元素个数：&quot;;			cin &gt;&gt; n;			for (int j = 0; j &lt; n; j++) &#123;				if (!DeQueue(S, e))					cout &lt;&lt; &quot;出队失败！&quot; &lt;&lt; endl;				else					cout &lt;&lt; &quot;第【&quot; &lt;&lt; j + 1 &lt;&lt; &quot;】个元素：&quot; &lt;&lt; e &lt;&lt; &quot; 出队成功！&quot; &lt;&lt; endl;			&#125;			break;		case 3:			if (!QueueTraverse(S))				cout &lt;&lt; &quot;队列为空!&quot; &lt;&lt; endl;			break;		case 4:			QueueLength(S);			break;		case 0:			return OK;		default:			return OK;		&#125;	&#125;	return 0;&#125;//循环队列的初始化Status InitQueue(SqQueue &amp;Q) &#123; //构造一个空队列Q	Q.base = new QElemType[MAXQSIZE];	if (!Q.base)		exit(OVERFLOW); //存储分配失败	Q.front = Q.rear = 0;	return OK;&#125;//循环队列的入队Status EnQueue(SqQueue &amp;Q, QElemType e) &#123; //插入元素e为Q的新的队尾元素	if ((Q.rear + 1) % MAXQSIZE == Q.front)		return ERROR; //尾指针在循环意义上加1后等于头指针，表明队满	Q.base[Q.rear] = e;	Q.rear = (Q.rear + 1) % MAXQSIZE;	return OK;&#125;//循环队列的出队Status DeQueue(SqQueue &amp;Q, QElemType &amp;e) &#123; //删除Q的队头元素，用e返回其值	if (Q.front == Q.rear)		return ERROR;	e = Q.base[Q.front];	Q.front = (Q.front + 1) % MAXQSIZE;	return OK;&#125;//输出循环队列Status QueueTraverse(SqQueue Q) &#123;	cout &lt;&lt; &quot;当前队列为：&quot;;	if (Q.front == Q.rear)		return ERROR;	while (Q.front != Q.rear) &#123;  //队列非空		cout &lt;&lt; Q.base[Q.front] &lt;&lt; &quot; &quot;;		Q.front = (Q.front + 1) % MAXQSIZE;	&#125;	cout &lt;&lt; endl;	return OK;  // ----------------------------------- 不返回结果的话 有的编译器无法编译通过&#125;//求循环队列长度Status QueueLength(SqQueue Q) &#123;  //返回Q的元素个数	int len = (Q.rear - Q.front + MAXQSIZE) % MAXQSIZE;	cout &lt;&lt; &quot;循环队列的长度为：&quot; &lt;&lt; len &lt;&lt; endl;	return OK;&#125;

