setAttribute(Qt::WA_TranslucentBackground);setWindowFlags(Qt::FramelessWindowHint);  // 此行windows下需

更多操作推荐参考博客：博客园：Qt界面外观之一：Qt风格与特殊效果窗体
QT可点击的进度条QT的QPushButton是有click()方法的，直接如下就可以：
connect(pushbutton, SIGNAL(clicked()), this, SLOT(on_pushbutton_clicked()));

但是QT的QProgressBar没有click()方法，需要我们手动处理鼠标事件。
可以写一个ClickableProgressBar类，继承QProgressBar：
class ClickableProgressBar : public QProgressBar &#123;public:    ClickableProgressBar(QWidget* parent = nullptr) : QProgressBar(parent) &#123;&#125;protected:    void mousePressEvent(QMouseEvent* event) override &#123;        qDebug() &lt;&lt; &quot;clickableProgressBar clicked&quot; &lt;&lt; endl;        for (int i = 0; i &lt;= 100; i++) &#123;            setValue(i);            Sleep(10);        &#125;    &#125;&#125;;

这样，在点击进度条时，就会从0到100逐渐填充完毕了。
完整代码main.cpp
